NETWORK_STATS_PATH = f"{BASE_STATS_DIR}/network/stats"

# --- Network & API Configuration ---
# Host IP address used for dashboard display and worker connectivity
HOST_IP = os.environ.get("HOST_IP", "Unknown Host")

# XMRig Worker API Configuration
XMRIG_API_PORT = 8080
API_TIMEOUT = 1         # Connection timeout (seconds) for worker API calls
UPDATE_INTERVAL = 30    # Frequency (seconds) of the main data aggregation loop

# --- XvB Algorithm Constants ---
# Duration of the donation switching cycle (10 minutes)
XVB_TIME_ALGO_MS = 600000

# Minimum dwell time on a pool to ensure valid share submission (15 seconds)
XVB_MIN_TIME_SEND_MS = 15000    

# Wallet address used for fetching XvB bonus history and pool identification
MONERO_WALLET_ADDRESS = os.environ.get("MONERO_WALLET_ADDRESS", "") 

# Unique Donor ID for the XMRvsBeast pool
XVB_DONOR_ID = os.environ.get("XVB_DONOR_ID", "")

# Feature Flag: Toggles the XvB algorithmic switching logic
ENABLE_XVB = os.environ.get("XVB_ENABLED", "true").lower() == "true"

# Donation tier to target (config.json: xvb.donation_level). The XvB raffle picks
# winners at random, so donating above a tier's threshold buys nothing — we aim to
# just clear it and send the rest to p2pool.
#   "auto" (default)  — highest tier the current hashrate can sustain
#   "donor"/"vip"/"whale"/"mega" — a specific named tier, honored even if the
#       hashrate can't sustain it (the dashboard shows a warning badge then)
XVB_DONATION_LEVEL = os.environ.get("XVB_DONATION_LEVEL", "auto").strip().lower()

# --- Upstream Pool Configuration ---
P2POOL_URL = os.environ.get("P2POOL_URL", "")
XVB_POOL_URL = os.environ.get("XVB_POOL_URL", "")

# --- Proxy API Configuration ---
PROXY_AUTH_TOKEN = os.environ.get("PROXY_AUTH_TOKEN", "")
PROXY_HOST = os.environ.get("PROXY_HOST", "127.0.0.1")
PROXY_API_PORT = int(os.environ.get("PROXY_API_PORT", 3344))

# --- Docker Proxy Configuration ---
# Read-only socket proxy: container stats/logs only (no write access).
DOCKER_PROXY_URL = os.environ.get("DOCKER_PROXY_URL", "tcp://172.28.0.30:2375")
# Control socket proxy: start/stop only, used to reject/readmit workers on node-down
# (Issue #31). A separate proxy so opening POST for start/stop can't widen the read-only
# proxy's access. See docker-compose.yml `docker-control`.
DOCKER_CONTROL_URL = os.environ.get("DOCKER_CONTROL_URL", "tcp://172.28.0.31:2375")
LOG_TAIL_LINES = int(os.environ.get("LOG_TAIL_LINES", 100))
DOCKER_TIMEOUT = int(os.environ.get("DOCKER_TIMEOUT", 5))

# --- Monero is required; Tari is optional (Issues #31, #35, #51) ---
# monerod is the chain the stack actually mines: if it's unreachable or still syncing, the
# workers can't mine no matter what, so those behaviours aren't configurable.
#   - A monerod outage ALWAYS rejects workers (stops xmrig-proxy → closes :3333) so miners
#     fail over to the backup pools they've configured instead of idling on us (Issue #31).
#   - The miner (p2pool + xmrig-proxy) is ALWAYS held until monerod has fully synced — it
#     can't mine against an unsynced node, and p2pool's merge-mining chatter would just flood
#     the logs during the hours-long initial sync (Issue #35).
#
# Tari is merge-mining gravy — you can mine Monero on p2pool without it — so a single flag,
# `dashboard.tari_required` (default true), decides how much Tari blocks the stack. When true
# (Tari treated as required), a Tari outage rejects workers, the miner waits for Tari's sync
# too, and a Tari-only (re)sync drives the full Sync-Mode dashboard. Set it false to make Tari
# NON-BLOCKING: keep mining Monero through a Tari outage, start the miner as soon as monerod is
# synced (Tari finishes in the background), and keep the operational dashboard — with a "Tari
# syncing" indicator — instead of the takeover screen (Issue #51).
TARI_REQUIRED = os.environ.get("TARI_REQUIRED", "true").strip().lower() == "true"

# Container the dashboard stops/starts to reject/readmit workers on a monerod/Tari outage.
REJECT_WORKERS_CONTAINER = os.environ.get("REJECT_WORKERS_CONTAINER", "xmrig-proxy")

# Containers held stopped until the required chain(s) finish syncing, then started together
# (p2pool first so the proxy has something to connect to). Comma-separated; order preserved.
# The hold is a one-way latch: after the first release we never re-hold (a later node blip is
# #31's job — it stops only xmrig-proxy so p2pool keeps its sidechain position), and the latch
# is persisted across dashboard restarts so a restart mid-sync doesn't prematurely release.
SYNC_GATE_CONTAINERS = [
    c.strip() for c in os.environ.get("SYNC_GATE_CONTAINERS", "p2pool,xmrig-proxy").split(",") if c.strip()
]

# Debounce: a node must be unreachable this long before it's declared DOWN, and reachable
# this long before recovery — so a single transient timeout or a brief restart doesn't
# kick every miner to their backups (and back) on a blip.
NODE_DOWN_AFTER_SEC = int(os.environ.get("NODE_DOWN_AFTER_SEC", 90))
NODE_RECOVERY_AFTER_SEC = int(os.environ.get("NODE_RECOVERY_AFTER_SEC", 60))

# --- Monero Configuration ---
# Used to determine if the node is local (Docker) or remote
MONERO_NODE_HOST = os.environ.get("MONERO_NODE_HOST", "172.28.0.26")

# monerod's get_info RPC, used to read sync height/target directly instead of scraping
# docker logs (Issue #29). Reachable because the dashboard runs network_mode: host and
# monerod publishes 127.0.0.1:18081. Credentials are required by monerod's restricted-rpc
# + rpc-login (digest auth); absent creds simply make the RPC fail and fall back to logs.
MONERO_RPC_URL = os.environ.get("MONERO_RPC_URL", "http://127.0.0.1:18081")
MONERO_NODE_USERNAME = os.environ.get("MONERO_NODE_USERNAME", "")
MONERO_NODE_PASSWORD = os.environ.get("MONERO_NODE_PASSWORD", "")

# Whether the bundled monerod is configured to prune the blockchain (config.json
# monero.prune → MONERO_PRUNE). Used to label the node Pruned/Full in the UI (Issue #32);
# only meaningful for a local node (we don't control a remote node's pruning).
MONERO_PRUNE = os.environ.get("MONERO_PRUNE", "true").strip().lower() == "true"

# --- Tari Configuration ---
# Connection details for the Tari Base Node and Block Explorer
TARI_GRPC_ADDRESS = os.environ.get("TARI_GRPC_ADDRESS", "127.0.0.1:18142")
TARI_EXPLORER_URL = "https://textexplore.tari.com/?json"

# --- XvB Donation Controller (Issue #9) ---
# Max fraction of any switching cycle donated to XvB. Always leaves room on p2pool
# so it keeps finding shares (required to stay a "VIP" and to validate raffle
# rounds) and caps how high a tier we will try to sustain. (Replaces the old
# hardcoded 0.85 tier-selection margin.)
XVB_MAX_DONATION_FRACTION = float(os.environ.get("XVB_MAX_DONATION_FRACTION", 0.85))

# Steady-state cushion held above the tier threshold so normal variance doesn't
# drop the measured 1h/24h average below it. A small percentage, but capped in
# ABSOLUTE H/s so high tiers don't over-donate (5% of 1M = 50k H/s wasted; the
# cap bounds that to a fixed amount regardless of tier).
XVB_MAINT_MARGIN_PCT = float(os.environ.get("XVB_MAINT_MARGIN_PCT", 0.02))
XVB_MAINT_MARGIN_ABS_CAP = float(os.environ.get("XVB_MAINT_MARGIN_ABS_CAP", 1000))

# Proportional catch-up gains: when a trailing average is below target, donate
# extra proportional to the deficit instead of dumping a full cycle. The 1h
# average recovers within the hour (larger gain); the 24h average is sluggish
# (gentle gain) to avoid sustained over-donation while it climbs.
XVB_CATCHUP_GAIN_1H = float(os.environ.get("XVB_CATCHUP_GAIN_1H", 1.5))
XVB_CATCHUP_GAIN_24H = float(os.environ.get("XVB_CATCHUP_GAIN_24H", 0.5))

# Switching overhead (ms) to account for connection ramp-up time
XVB_SWITCH_OVERHEAD_MS = 5000

# --- Data Retention Policies ---
HISTORY_RETENTION_SEC = 30 * 24 * 3600  # 30 Days
WORKER_RETENTION_SEC = 7 * 24 * 3600    # 7 Days

# --- Donation Tier Configuration ---
# Hashrate thresholds (H/s) for XMRvsBeast donation tiers.
# Reference: Official XvB rules (Mega=1M, Whale=100k, VIP=10k, Donor=1k)
TIER_DEFAULTS = {
    "donor_mega": 1_000_000, 
    "donor_whale": 100_000, 
    "donor_vip": 10_000,    
    "donor": 1_000          
}

# Allow runtime configuration override via environment variable (injected via .env)
env_tiers = os.environ.get("TIER_CONFIG")
if env_tiers and env_tiers.strip() and env_tiers != "''":
    try:
        custom_tiers = json.loads(env_tiers.strip("'"))
        if isinstance(custom_tiers, dict):
            TIER_DEFAULTS = custom_tiers
    except json.JSONDecodeError:
        pass

